INSERT INTO sys_role_permission(id,role_id,permission_id,effect) SELECT 2201000000000110000+ROW_NUMBER() OVER(ORDER BY r.id,p.id),r.id,p.id,'ALLOW' FROM sys_role r JOIN sys_permission p ON (p.permission_code='ORGANIZATION_ONBOARDING_REVIEW' AND r.role_code IN ('SYS_ADMIN','SYS_AUDITOR')) OR (p.permission_code='ORGANIZATION_OWNER_TRANSFER' AND r.role_code IN ('PARENT_ADMIN','ORG_ADMIN')) WHERE r.status='ENABLED';
