-- Add onboarding permissions and menus only; preserve existing grants, order and enabled states.
UPDATE sys_permission SET parent_id=(SELECT id FROM (SELECT id FROM sys_permission WHERE permission_code='ORGANIZATION_ONBOARDING_READ') parent_permission) WHERE permission_code='ORGANIZATION_ONBOARDING_SUBMIT';
UPDATE sys_permission SET parent_id=(SELECT id FROM (SELECT id FROM sys_permission WHERE permission_code='ORGANIZATION_ONBOARDING_READ') parent_permission) WHERE permission_code='ORGANIZATION_OWNER_TRANSFER';
UPDATE sys_permission SET parent_id=(SELECT id FROM (SELECT id FROM sys_permission WHERE permission_code='SYSTEM_TASK_READ') parent_permission) WHERE permission_code='ORGANIZATION_ONBOARDING_REVIEW';
